        public async Task<RTPstat> RtpstatisticsAsync(string channelId)
        {
            var url = "channels/{channelId}/rtp_statistics";
            return await _client.GetAsync<RTPstat>(url);
        }

        public Channel ExternalMedia(string app, string external_host, string format, string? channelId = null, Dictionary<string, string> variables = null, string? encapsulation = null, string? transport = null, string? connection_type = null, string? direction = null, string? data = null)
        {
            return ExternalMediaAsync(channelId: channelId, app: app, variables: variables, external_host: external_host, encapsulation: encapsulation, transport: transport, connection_type: connection_type, format: format, direction: direction, data: data).GetAwaiter().GetResult();
        }

        public async Task<Channel> ExternalMediaAsync(string app, string external_host, string format, string? channelId = null, Dictionary<string, string> variables = null, string? encapsulation = null, string? transport = null, string? connection_type = null, string? direction = null, string? data = null)
        {
            var url = "channels/externalMedia";
            if (!string.IsNullOrEmpty(channelId)) url += (url.Contains("?") ? "&" : "?") + "channelId=" + System.Uri.EscapeDataString(channelId);
            if (!string.IsNullOrEmpty(app)) url += (url.Contains("?") ? "&" : "?") + "app=" + System.Uri.EscapeDataString(app);
            if (!string.IsNullOrEmpty(external_host)) url += (url.Contains("?") ? "&" : "?") + "external_host=" + System.Uri.EscapeDataString(external_host);
            if (!string.IsNullOrEmpty(encapsulation)) url += (url.Contains("?") ? "&" : "?") + "encapsulation=" + System.Uri.EscapeDataString(encapsulation);
            if (!string.IsNullOrEmpty(transport)) url += (url.Contains("?") ? "&" : "?") + "transport=" + System.Uri.EscapeDataString(transport);
            if (!string.IsNullOrEmpty(connection_type)) url += (url.Contains("?") ? "&" : "?") + "connection_type=" + System.Uri.EscapeDataString(connection_type);
            if (!string.IsNullOrEmpty(format)) url += (url.Contains("?") ? "&" : "?") + "format=" + System.Uri.EscapeDataString(format);
            if (!string.IsNullOrEmpty(direction)) url += (url.Contains("?") ? "&" : "?") + "direction=" + System.Uri.EscapeDataString(direction);
            if (!string.IsNullOrEmpty(data)) url += (url.Contains("?") ? "&" : "?") + "data=" + System.Uri.EscapeDataString(data);
            return await _client.PostAsync<Channel>(url);
        }

    }
